using System.Text.Json;
using Peel.Windows.Protocol;

namespace Peel.Windows.Protocol.Tests;
internal static partial class Program
{
    private static void MachineStatusProofContract()
    {
        // Independently generated by Swift CryptoKit on the reference Mac, October 4, 2026.
        var challenge = new AgentPairingChallengeMessage("01234567-89ab-cdef-0123-456789abcdef", "windows-test-peer",
            Convert.ToBase64String(Enumerable.Range(0, 32).Select(i => (byte)i).ToArray()), 1791150000.25);
        byte[] key = Enumerable.Range(32, 32).Select(i => (byte)i).ToArray();
        string proof = AgentPairingProof.Make(challenge, key);
        Equal("ZecG/PUn4ELn0VlmYMg1CVLkQgI3kugHJ1OSdu8vniU=", proof);
        True(AgentPairingProof.Verify(proof, challenge, key));
        True(!AgentPairingProof.Verify(proof, challenge with { PairingId = "other" }, key));
        True(!AgentPairingProof.Verify("malformed", challenge, key));
        True(!AgentPairingProof.IsFresh(challenge, challenge.ExpiresAt));
        True(!AgentPairingProof.IsFresh(challenge, challenge.ExpiresAt - 61));
        var status = new MachineStatusMessage(Guid.NewGuid().ToString(), 1791150000, "Test", CpuFraction: .3);
        PeelJson.Deserialize<MachineStatusMessage>(PeelJson.Serialize(status)).Validate();
        Throws<InvalidDataException>(() => (status with { CpuFraction = double.NaN }).Validate());
        Throws<InvalidDataException>(() => (status with { BatteryFraction = 1.1 }).Validate());
        Throws<InvalidDataException>(() => (status with { HostName = "host\nspoof" }).Validate());
        Throws<InvalidDataException>(() => (status with { RequestId = "abc" }).Validate());
        Throws<InvalidDataException>(() => (status with { TopApps = Enumerable.Repeat(new MachineStatusApp("test", 1, 0, 0), 6).ToArray() }).Validate());
        Throws<JsonException>(() => PeelJson.Deserialize<MachineStatusMessage>(System.Text.Encoding.UTF8.GetBytes("{\"type\":\"machineStatus\",\"memoryUsedBytes\":-1}")));
    }
}
